function mark(e){const tool=$('site-tool').value;if(tool==='none'||view!=='top')return;const rect=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const p=new THREE.Vector3();if(!ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),p))return;const point={x:Math.round(p.x*10)/10,z:Math.round(p.z*10)/10};if(tool==='takeoff'){site.takeoff=point;refresh();}else if(tool==='obstacle'){const radius=num('site-radius');if(!(radius>=2))return;site.obstacles.push({...point,radius});refresh();}else if(!first){first=point;status('已标记第一角，请点区域对角');}else{const width=Math.abs(point.x-first.x),depth=Math.abs(point.z-first.z);if(width<1||depth<1){first=null;status('区域过小，请重新标注');return;}site.buildings.push({name:'巡检区域 '+(site.buildings.length+1),x:(point.x+first.x)/2,z:(point.z+first.z)/2,width,depth,height:Math.max(0,num('site-height'))});first=null;refresh();status('已生成建筑示意与巡检范围');}}
