 if(!['glb','gltf'].includes(ext))throw Error('暂时无法读取该模型，请联系建模人员提供适用于网页展示的模型文件。');const buffer=await file.arrayBuffer();let data;if(ext==='glb'){const dv=new DataView(buffer);if(dv.getUint32(0,true)!==0x46546c67||dv.getUint32(4,true)!==2)throw Error('仅支持 glTF 2.0');const len=dv.getUint32(12,true);data=JSON.parse(new TextDecoder().decode(new Uint8Array(buffer,20,len)).trim());}else data=JSON.parse(new TextDecoder().decode(buffer));
 if((data.extensionsRequired||[]).some(x=>/draco|meshopt|basisu/i.test(x)))throw Error('请导出未使用 Draco / Meshopt / KTX 压缩的 GLB');if([...(data.buffers||[]),...(data.images||[])].some(x=>x.uri&&!x.uri.startsWith('data:')))throw Error('请将纹理和几何内嵌后导出 GLB，暂不加载外部文件');
