const controlDialog=document.createElement('dialog');controlDialog.className='owner-dialog';controlDialog.innerHTML=`<div class="dialog-head"><strong>控制点校准</strong><button type="button" class="icon-button" aria-label="关闭">×</button></div><p class="project-hint">在图上选两个相距较远的已知点，填写同一平面坐标系的实测坐标（米）。</p><form id="control-form">${[0,1].map(i=>`<div class="control-point-row"><button type="button" data-pick-control="${i}">选取 P${i+1}</button><span id="control-position-${i}">未选点</span><label>X / 东坐标（米）<input id="control-x-${i}" type="number" step="any" required></label><label>Y / 北坐标（米）<input id="control-y-${i}" type="number" step="any" required></label></div>`).join('')}<p id="control-result" role="status"></p><button type="submit" class="primary">校准尺寸</button></form><p class="project-hint">不填经纬度。两点校准适用于等比例俯视图，不能消除斜拍畸变。</p>`;document.body.append(controlDialog);controlDialog.querySelector('button').onclick=()=>controlDialog.close();
