function solvePhotoCalibration(points,aspect){const [a,b]=points;if(!a||!b)throw Error('请先选取 P1、P2');const px=(b.pixel.x-a.pixel.x)/1000,py=-(b.pixel.y-a.pixel.y)/1000/aspect,dx=b.x-a.x,dy=b.y-a.y,span=Math.hypot(px,py),distance=Math.hypot(dx,dy);if(![px,py,dx,dy].every(Number.isFinite)||span<.03||distance<.1)throw Error('控制点太近或坐标无效，请重新选择');const width=distance/span;if(width<10||width>5000)throw Error('校准宽度超出 10—5000 米，请检查坐标单位');const angle=Math.atan2(dy,dx)-Math.atan2(py,px),cos=Math.cos(angle),sin=Math.sin(angle),lx=(a.pixel.x/1000-.5)*width,ly=-(a.pixel.y/1000-.5)*width/aspect;return {width,rotationRadians:angle,origin:{x:a.x-cos*lx+sin*ly,y:a.y-sin*lx-cos*ly},units:'meters',axes:'worldX=origin.x+cos(angle)*local.x+sin(angle)*local.z; worldY=origin.y+sin(angle)*local.x-cos(angle)*local.z'};}
