const craneDialog=document.createElement('dialog');craneDialog.className='owner-dialog photo-height-dialog';craneDialog.innerHTML=`<div class="dialog-head"><strong>塔吊设置</strong><button type="button" class="icon-button" aria-label="关闭">×</button></div><form id="crane-form"><label>塔吊高度（米）<input id="crane-height" type="number" min="5" max="200" step="any" required></label><label>回转半径（米）<input id="crane-radius" type="number" min="2" max="100" step="any" required></label><p class="project-hint">航线根据塔吊高度与回转半径规划，并预留安全净距。</p><div class="notice-toolbar"><button type="submit" class="primary">保存塔吊</button><button type="button" id="crane-delete" class="icon-button crane-delete-button" aria-label="删除塔吊" title="删除塔吊">${craneTrashIcon}</button></div></form>`;document.body.append(craneDialog);let editingCrane=null,newCrane=false;craneDialog.querySelector('button').onclick=()=>craneDialog.close();function openCrane(o,fresh){ensureCraneIds();craneDialog.querySelector('strong').textContent=fresh?'新增塔吊':craneName(o)+' · 设置';editingCrane=o;newCrane=fresh;$('crane-height').value=o.height;$('crane-radius').value=o.radius;$('crane-delete').hidden=fresh;craneDialog.showModal();}$('crane-form').onsubmit=e=>{e.preventDefault();if(!$('crane-form').reportValidity())return;editingCrane.height=num('crane-height');editingCrane.radius=num('crane-radius');if(newCrane){editingCrane.craneId=nextCraneId++;site.obstacles.push(editingCrane);}craneDialog.close();refresh();};$('crane-delete').onclick=()=>{const i=site.obstacles.indexOf(editingCrane);if(i>=0)site.obstacles.splice(i,1);craneDialog.close();refresh();};
