function installSiteNavigation(canvas){const controls=document.createElement('div');controls.className='site-nav-controls';controls.innerHTML='<button type="button" aria-label="放大模型" title="放大">＋</button><button type="button" aria-label="缩小模型" title="缩小">−</button><button type="button" aria-label="恢复全景" title="恢复全景">⌖</button>';$('site-view').append(controls);const [plus,minus,reset]=controls.children;plus.onclick=()=>zoomSite(1.2);minus.onclick=()=>zoomSite(1/1.2);reset.onclick=()=>{camera.zoom=1;siteOrbitYaw=.58;siteOrbitPitch=.62;sitePan.set(0,0,0);camera.updateProjectionMatrix();setView(view);};canvas.addEventListener('wheel',e=>{e.preventDefault();zoomSite(Math.exp(-e.deltaY*.001));},{passive:false});const pointers=new Map();let distance=0;canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});canvas.setPointerCapture(e.pointerId);if(pointers.size===2){const [a,b]=[...pointers.values()];distance=Math.hypot(a.x-b.x,a.y-b.y);}});canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],next=Math.hypot(a.x-b.x,a.y-b.y);if(distance>5)zoomSite(next/distance);distance=next;}});for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{pointers.delete(e.pointerId);distance=0;});}
