function updateCraneManager(){const cranes=site.obstacles.filter(o=>o.kind==='crane');craneManageButton.textContent=photoCraneManageButton.textContent='塔吊管理 · '+cranes.length;const list=$('site-crane-list');list.replaceChildren();if(!cranes.length){list.textContent='暂无塔吊，可在照片标注页点击“塔吊”放置。';return;}cranes.forEach((o,i)=>{const row=document.createElement('div');row.className='crane-manage-row';row.innerHTML=`<div><strong>${esc(craneName(o))}</strong><small>高度 ${o.height} m · 回转半径 ${o.radius} m</small></div><button type="button" class="crane-edit">编辑</button><button type="button" class="crane-remove icon-button crane-delete-button" aria-label="删除${esc(craneName(o))}" title="删除${esc(craneName(o))}">${craneTrashIcon}</button>`;row.querySelector('.crane-edit').onclick=()=>{craneManager.close();openCrane(o,false);};row.querySelector('.crane-remove').onclick=()=>{site.obstacles.splice(site.obstacles.indexOf(o),1);refresh();updateCraneManager();status('塔吊已删除，请重新生成航线');};list.append(row);});}
function siteRoadDetails(w,d){const road=Math.max(3,Math.min(w,d)*.045),color=0xb7c6ce;function roadStrip(x,z,rw,rd,vertical){modelBox(group,rw,.06,rd,x,.03,z,color);const len=vertical?rd:rw,step=Math.max(5,len/35);for(let t=-len/2+step/2;t<len/2;t+=step)modelBox(group,vertical?.08:step*.36,.025,vertical?step*.36:.08,x+(vertical?0:t),.08,z+(vertical?t:0),0xf5fafb);for(const side of [-1,1])modelBox(group,vertical?.18:rw,.14,vertical?rd:.18,x+(vertical?side*rw/2:0),.09,z+(vertical?0:side*rd/2),0xeaf2f3);}
function corridors(axis,max){const intervals=site.buildings.map(b=>{const center=b[axis],span=axis==='x'?b.width:b.depth;return [center-span/2-road*.3,center+span/2+road*.3];}).sort((a,b)=>a[0]-b[0]),gaps=[];let edge=-max/2;for(const [a,b] of intervals){if(a-edge>road*1.4)gaps.push([edge,a]);edge=Math.max(edge,b);}if(max/2-edge>road*1.4)gaps.push([edge,max/2]);return gaps.sort((a,b)=>(b[1]-b[0])-(a[1]-a[0])).slice(0,2);}
for(const [a,b] of corridors('x',w))roadStrip((a+b)/2,0,road,d,true);for(const [a,b] of corridors('z',d))roadStrip(0,(a+b)/2,w,road,false);const outer=Math.max(2,Math.min(w,d)*.07);for(const x of [-w/2-outer/2,w/2+outer/2])roadStrip(x,0,outer,d,true);for(const z of [-d/2-outer/2,d/2+outer/2])roadStrip(0,z,w+outer*2,outer,false);for(const x of [-w/2-outer,w/2+outer]){modelBox(group,.2,.7,d, x,.3,0,0x94b3be);const count=Math.max(4,Math.min(24,Math.floor(d/10)));for(let i=0;i<=count;i++){const tree=new THREE.Mesh(new THREE.SphereGeometry(Math.min(1.3,outer*.27),7,5),new THREE.MeshStandardMaterial({color:0x96b8ad,roughness:1}));tree.position.set(x,1,-d/2+d*i/count);tree.castShadow=true;group.add(tree);}}}
