const envelopeButton=document.createElement('button');envelopeButton.type='button';envelopeButton.textContent='安全包络';envelopeButton.setAttribute('aria-pressed','true');envelopeButton.className='active';const parameterHeading=document.createElement('div');parameterHeading.className='settings-heading';parameterHeading.innerHTML='<strong>飞行参数</strong>';const parameterActions=document.createElement('div');parameterActions.append(envelopeButton);const replanButton=document.createElement('button');replanButton.type='button';replanButton.textContent='⤳ 重新规划';replanButton.onclick=()=>$('site-plan').click();parameterActions.append(replanButton);parameterHeading.append(parameterActions);flightGrid.before(parameterHeading);let droneEnvelope=null,envelopeVisible=true;envelopeButton.onclick=()=>{envelopeVisible=!envelopeVisible;envelopeButton.classList.toggle('active',envelopeVisible);envelopeButton.setAttribute('aria-pressed',String(envelopeVisible));if(droneEnvelope)droneEnvelope.visible=envelopeVisible;};let flightInfoLast=0;
function updateImportedFlightInfo(){if(!$('imported-drone-state'))return;const now=performance.now();if(running&&now-flightInfoLast<200)return;flightInfoLast=now;if(drone&&!droneEnvelope){droneEnvelope=new THREE.Mesh(new THREE.SphereGeometry(1,14,10),new THREE.MeshBasicMaterial({color:0x799df2,wireframe:true,transparent:true,opacity:.18,depthWrite:false}));drone.add(droneEnvelope);}if(droneEnvelope){droneEnvelope.scale.setScalar(Math.max(2,num('site-clearance')));droneEnvelope.visible=envelopeVisible;}
let traveled=0;if(plan){for(let i=1;i<=Math.min(segment,plan.route.length-1);i++){const a=plan.route[i-1],b=plan.route[i];traveled+=Math.hypot(b.x-a.x,b.y-a.y,b.z-a.z);}traveled+=progress;}const finished=!!plan&&segment>=plan.route.length-1,percent=plan?Math.min(100,Math.round(traveled/plan.distance*100)):0;$('imported-drone-state').textContent=!plan?'待规划':finished?'DJI · 已降落':!running?'DJI · 已暂停':segment===0?'DJI · 垂直起飞':segment===plan.route.length-2?'DJI · 降落':'DJI · 巡检中';$('imported-height').innerHTML=(plan?Math.max(0,(drone?.position.y||.8)-.8).toFixed(1):'—')+' <small>m</small>';$('imported-speed').innerHTML=(running?num('site-speed').toFixed(1):'0.0')+' <small>m/s</small>';$('imported-progress').innerHTML=percent+'<small>%</small>';$('imported-progress-bar').style.width=percent+'%';$('imported-time').textContent=plan?(plan.distance/Math.max(1,num('site-speed'))/60).toFixed(1)+' min':'—';$('imported-route-summary').textContent=plan?`航线 ${plan.distance.toFixed(0)} m · 航高 ${plan.altitude.toFixed(1)} m · 安全净距 ${num('site-clearance')} m`+(plan.restrictedLength>0?` · 受限巡检线 ${plan.restrictedLength.toFixed(1)} m 未覆盖`:'')+(plan.skippedRegions.length?' · 未覆盖区域：'+plan.skippedRegions.join('、'):''):'设置场地后生成巡检航线';const routeKey=plan?plan.visitedRegions.join('|'):'none';if(flightInfo.dataset.routeKey!==routeKey){flightInfo.dataset.routeKey=routeKey;$('imported-route-stops').innerHTML=plan?['起飞点',...plan.visitedRegions,'返航降落'].map((name,i)=>'<span class="stop"><i>'+ (i===0||i===plan.visitedRegions.length+1?'H':String(i).padStart(2,'0'))+'</i>'+esc(name)+'</span>').join(''):'';}}
const siteGestureHint=document.createElement('p');siteGestureHint.className='site-gesture-hint';siteGestureHint.textContent='拖动旋转 · 右键 / Shift 拖动平移 · 滚轮或双指缩放';$('site-view').after(siteGestureHint);
for(const [id,label,unit] of [['site-altitude','目标航高','m'],['site-clearance','安全净距','m'],['site-speed','飞行速度','m/s'],['site-spacing','巡检间距','m']]){const input=$(id),limit=FLIGHT_LIMITS[id.replace('site-','')];input.min=limit.min;input.max=limit.max;input.value=limit.default;const wrapper=input.closest('label'),title=document.createElement('span'),output=document.createElement('output');title.className='imported-setting-title';title.textContent=label;output.textContent=input.value+' '+unit;title.append(output);for(const node of [...wrapper.childNodes])if(node!==input)node.remove();wrapper.prepend(title);input.type='range';input.step=id==='site-speed'?'.5':'1';input.addEventListener('input',()=>{output.textContent=input.value+' '+unit;});}

function installCranePicking(canvas){let start=null;const pointers=new Set();canvas.addEventListener('pointerdown',e=>{pointers.add(e.pointerId);start=pointers.size===1&&e.button===0?{id:e.pointerId,x:e.clientX,y:e.clientY}:null;});canvas.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>5)start=null;});canvas.addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);start=null;});canvas.addEventListener('pointerup',e=>{pointers.delete(e.pointerId);const hit=start;start=null;if(!hit||hit.id!==e.pointerId||Math.hypot(e.clientX-hit.x,e.clientY-hit.y)>5||($('site-tool').value!=='none'&&view==='top'&&source!=='photo'))return;const rect=canvas.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),camera);for(const intersection of ray.intersectObjects(group.children,true)){let object=intersection.object;while(object&&object!==group){if(object.userData.crane){openCrane(object.userData.crane,false);return;}object=object.parent;}}});}

function selectCraneLabel(e){const label=e.target.closest('[data-crane-id]');if(!label)return;const crane=site.obstacles.find(o=>o.kind==='crane'&&o.craneId===Number(label.dataset.craneId));if(crane){e.preventDefault();e.stopPropagation();openCrane(crane,false);}}
$('photo-labels').addEventListener('click',selectCraneLabel);
$('photo-labels').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')selectCraneLabel(e);});
